with latest as (select * from orders qualify row_number() over (partition by store_id order by order_date desc, id) = 1) select channel, date_trunc('month', order_date) as activity_month, case when discount >= 0.38 then 'HIGH' else 'LOW' end as discount_tier, sum(case when channel = 'web' then discount else 0 end) as web_discount, size(collect_set(channel)) as num_channels, max(shipping_fee) filter (where channel = 'mobile') as mobile_max_shipping_fee, stddev_samp(discount) as discount_stddev, count(distinct store_id) as distinct_store_ids, round(avg(amount), 2) as avg_amount from latest group by channel, date_trunc('month', order_date), case when discount >= 0.38 then 'HIGH' else 'LOW' end order by channel;
